import{text,list,identifiers,choice}from'../creative-kit/state.js?v=0.16.0';
export const TYPES={fact:'Facts',cause:'Causes',value:'Values',design:'Possible designs'};export const FIELDS=['question','unlocks','evidence','answer','ideas'];
export const question=(id,type='fact')=>({id,type,parent:null,relation:'original',question:'',unlocks:'',evidence:'',answer:'',ideas:'',status:'open'});
export function make(id='first',example='example'){const w={id,problem:example==='blank'?'':'We need better forecasts. What do we need to understand before choosing a response?',items:[question('q1')],selected:[],phase:'expand'};if(example!=='blank'){w.items=[{...question('q1'),question:'Which decision would actually change with a better forecast?',unlocks:'Whether to improve prediction or change the decision rule.'},{...question('q2','cause'),question:'Why do forecast errors lead to costly actions?',unlocks:'Whether a buffer, review trigger or different contract could help.'},{...question('q3','value'),question:'Which matters more here: a missed opportunity or an avoidable commitment?',unlocks:'The tradeoff the decision rule should make explicit.'},{...question('q4','design'),question:'How could the decision remain useful when the forecast is wrong?',unlocks:'Ideas that improve robustness without demanding perfect accuracy.'}];w.selected=['q1','q4'];}return w;}
export function validate(w){list(w.items,28);identifiers(w.items);choice(w.phase,['expand','develop']);const seen=new Set();for(const q of w.items){FIELDS.forEach(f=>text(q[f]));choice(q.type,Object.keys(TYPES));choice(q.status,['open','hypothesis','supported']);choice(q.relation,['original','expand','invert']);if(q.parent!==null&&!seen.has(q.parent))throw Error('A question’s parent must appear before it.');seen.add(q.id);}list(w.selected,6);if(new Set(w.selected).size!==w.selected.length||w.selected.some(id=>!seen.has(id)))throw Error('Question selection is inconsistent.');return w;}
export function apply(w,a){if(a.type==='edit'){const q=w.items.find(x=>x.id===a.item);if(!q)throw Error('Question is missing.');choice(a.field,[...FIELDS,'status','type']);q[a.field]=a.field==='status'?choice(a.value,['open','hypothesis','supported']):a.field==='type'?choice(a.value,Object.keys(TYPES)):text(a.value);}else if(a.type==='add')w.items.push(question(a.id,a.kind||'fact'));else if(a.type==='branch'){const parent=w.items.find(q=>q.id===a.parent);if(!parent)throw Error('Parent question is missing.');choice(a.relation,['expand','invert']);w.items.push({...question(a.id,parent.type),parent:parent.id,relation:a.relation,question:a.relation==='invert'?`What changes if the opposite is true: ${parent.question}`:`What would we need to know to answer: ${parent.question}`});}else if(a.type==='move'){const q=w.items.find(q=>q.id===a.id);if(!q)throw Error('Question is missing.');q.type=choice(a.kind,Object.keys(TYPES));}else if(a.type==='select'){if(!w.items.some(q=>q.id===a.id))throw Error('Question is missing.');if(w.selected.includes(a.id))w.selected=w.selected.filter(id=>id!==a.id);else{if(w.selected.length>=6)throw Error('Develop at most six questions at once.');w.selected.push(a.id);}}else if(a.type==='remove'){if(w.items.some(q=>q.parent===a.id))throw Error('This question has branches. Remove the branches first, or keep it open.');w.items=w.items.filter(q=>q.id!==a.id);w.selected=w.selected.filter(id=>id!==a.id);}else if(a.type==='phase')w.phase=choice(a.phase,['expand','develop']);else throw Error('Unknown question action.');}
export function markdown(w){return ['# Questions before answers','',w.problem,'',...w.items.flatMap(q=>[`## ${q.question||'Untitled question'}`,'',`${TYPES[q.type]} · ${q.status}${w.selected.includes(q.id)?' · selected for development':''}`,`Parent: ${q.parent?w.items.find(p=>p.id===q.parent)?.question:'Original question'} (${q.relation})`,'',...FIELDS.slice(1).flatMap(f=>[`**${f}**`,q[f]||'_Not written._',''])])].join('\n');}
